<script setup lang="ts">
import RecordSelect from '../components/RecordSelect.vue'
import {ref,reactive,computed,watch,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,type FormInstance, type UploadFile} from 'element-plus'
import type {Row} from '../api/types'
import {post,put,downloadAttachment} from '../api/http'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,confirmAction,today} from '../composables/useResource'
import {remove} from '../api/http'
import {usePagedResource} from '../composables/usePagedResource'
import ExchangeActions from '../components/ExchangeActions.vue'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
import PaymentPlanEditor from '../components/PaymentPlanEditor.vue'
const route=useRoute(),auth=useAuth(),listing=usePagedResource('/records/contracts'),{data,loading,error,load,paging,onPage,onSize,onSearch}=listing
const editorTab=ref('header'),planRef=ref<any>()
const orders=ref<Row[]>([]),orderLoading=ref(false),dialog=ref(false),selected=ref<Row>(),file=ref<File>(),formRef=ref<FormInstance>()
const form=reactive<Record<string,any>>({}),{saving,run}=useMutation(load),downloading=ref<any>('')
const fields=[['code','合同编号'],['name','合同名称'],['amount','合同金额（元）'],['signed_date','签订日期'],['start_date','开始日期'],['end_date','结束日期']]
const options=computed(()=>orders.value.filter(o=>String(o.project_id)===String(form.project_id)&&(!form.supplier_id||String(o.supplier_id)===String(form.supplier_id))))
async function edit(row?:Row){editorTab.value='header';selected.value=row;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{code:'',name:'',type:'MAIN',project_id:'',supplier_id:null,order_id:null,amount:'',signed_date:today(),start_date:today(),end_date:'',status:'DRAFT',payment_plan:'[]'},row?Object.fromEntries(['code','name','type','project_id','supplier_id','order_id','amount','signed_date','start_date','end_date','status','payment_plan'].map(k=>[k,row[k]])):{});file.value=undefined;dialog.value=true;formRef.value?.clearValidate();}

watch(()=>form.project_id,(next,prev)=>{if(prev&&next!==prev)form.order_id=null})
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;if(!Number.isFinite(Number(form.amount))||Number(form.amount)<0||String(form.amount).trim()===''){ElMessage.warning('请填写有效合同金额');return}if(form.end_date<form.start_date){ElMessage.warning('合同结束日期不得早于开始日期');return}const {payment_plan:legacyPlan,...header}=form;const payload={...header,supplier_id:form.supplier_id||null,order_id:form.order_id||null,};let savedId=selected.value?.id;if(await run(async()=>{const result=await(selected.value?put<Row>(`/contracts/${selected.value.id}`,payload):post<Row>('/contracts',payload));savedId=savedId||result?.id;selected.value={...header,...result,id:savedId};if(file.value){if(!savedId)throw new Error('服务端未返回合同 ID，无法上传附件');const fd=new FormData();fd.append('file',file.value);try{await post(`/contracts/${savedId}/attachment`,fd);file.value=undefined}catch(e){selected.value={...payload,id:savedId};await load();ElMessage.warning('合同已保存，附件上传失败；可重试保存，仅更新此合同');throw e}}},'合同及附件已保存')){await load();editorTab.value='plan'}}
function selectFile(upload:UploadFile){if(!upload.raw)return;if(upload.raw.size>10*1024*1024){ElMessage.warning('附件不可超过 10MB');file.value=undefined;return}file.value=upload.raw}
async function download(row:Row){downloading.value=row.id;try{await downloadAttachment(row.id,row.attachment_name)}catch(e){ElMessage.error(e instanceof Error?e.message:'下载失败')}finally{downloading.value=''}}
async function drop(row:Row){if(await confirmAction('确认删除该合同？有关联业务时将由服务端拒绝。'))await run(()=>remove(`/contracts/${row.id}`),'合同已删除')}
onMounted(async()=>{if(route.query.contract_id){const {get}=await import('../api/http');try{const row=await get<Row>(`/contracts/${route.query.contract_id}`);await edit(row);editorTab.value='plan'}catch{}}})
</script>
<template><PageHeader title="合同管理" subtitle="关联项目与采购订单，统一管理合同条款、付款计划和原始附件。"><ExchangeActions entity="contracts" :filters="{q:paging.q}"/><el-button :loading="loading" @click="load">刷新</el-button><el-button v-if="auth.can('contract:write')" type="primary" @click="edit()">＋ 新建合同</el-button></PageHeader><section class="panel table-panel"><ResourceState :loading="loading" :error="error" @retry="load"><DataTable :remote="paging" @page="onPage" @size="onSize" @search="onSearch" :rows="data" :action-width="235" :columns="[{key:'code',label:'合同编号',minWidth:160},{key:'name',label:'合同名称',minWidth:200},{key:'project_name',label:'关联项目',minWidth:190},{key:'type',label:'合同类型',status:true,width:115},{key:'amount',label:'合同金额（元）',money:true,minWidth:155},{key:'signed_date',label:'签订日期',width:125},{key:'status',label:'状态',status:true,width:100}]"><template #actions="{row}"><el-button v-if="row.attachment_name" link type="primary" :loading="downloading===row.id" @click="download(row)">附件</el-button><el-button link type="primary" @click="edit(row)">{{auth.can('contract:write')?'编辑':'详情'}}</el-button><el-button v-if="auth.can('contract:write')" link type="danger" @click="drop(row)">删除</el-button></template></DataTable></ResourceState></section><el-dialog v-model="dialog" :title="selected?'合同信息':'新建合同'" width="840px" :close-on-click-modal="false" destroy-on-close><el-tabs v-model="editorTab"><el-tab-pane label="合同基本信息" name="header"><el-form ref="formRef" :model="form" label-position="top" :disabled="!auth.can('contract:write')"><div class="form-grid"><el-form-item v-for="[key,label] in fields" :key="key" :label="label" :prop="key" :rules="[{required:true,message:`请填写${label}`}]"><el-date-picker v-if="key.endsWith('date')" v-model="form[key]" type="date" value-format="YYYY-MM-DD" style="width:100%"/><el-input v-else v-model="form[key]" :disabled="key==='amount'&&!!selected?.id&&!auth.can('finance:read')" :inputmode="key==='amount'?'decimal':undefined"/></el-form-item><el-form-item label="合同类型" prop="type" :rules="[{required:true,message:'请选择合同类型'}]"><el-select v-model="form.type"><el-option label="总包合同" value="MAIN"/><el-option label="采购合同" value="PURCHASE"/><el-option label="分包合同" value="SUBCONTRACT"/></el-select></el-form-item><el-form-item label="关联项目" prop="project_id" :rules="[{required:true,message:'请选择关联项目'}]"><RecordSelect v-model="form.project_id" entity="projects"/></el-form-item><el-form-item label="关联供应商（可选）"><RecordSelect v-model="form.supplier_id" @change="form.order_id=null" entity="suppliers"/></el-form-item><el-form-item label="关联订单（可选）"><RecordSelect v-if="auth.can('order:read')" v-model="form.order_id" entity="orders" :filters="{project_id:form.project_id,supplier_id:form.supplier_id}" :disabled="!auth.can('finance:read')"/><el-input v-else :model-value="form.order_id?'订单 #'+form.order_id:'未关联'" disabled/></el-form-item><el-form-item label="合同状态"><el-select v-model="form.status"><el-option label="草稿" value="DRAFT"/><el-option label="执行中" value="ACTIVE"/><el-option label="已完成" value="COMPLETED"/></el-select></el-form-item><el-form-item label="原始附件（最大 10MB）"><el-upload :auto-upload="false" :limit="1" :show-file-list="false" :on-change="selectFile"><el-button>选择附件</el-button></el-upload><span class="field-hint">{{file?.name||selected?.attachment_name||'尚未选择附件'}}</span></el-form-item></div></el-form></el-tab-pane><el-tab-pane label="付款计划与实际关联" name="plan"><PaymentPlanEditor v-if="selected?.id&&editorTab==='plan'" ref="planRef" :id="selected.id"/><el-empty v-else description="请先保存合同基本信息，再维护付款计划"/></el-tab-pane></el-tabs><template #footer><el-button @click="dialog=false">关闭</el-button><el-button v-if="editorTab==='header'&&auth.can('contract:write')" type="primary" :loading="saving" @click="save">保存合同</el-button><el-button v-if="editorTab==='plan'&&auth.can('contract:plan')&&auth.can('contract:write')&&auth.can('finance:read')" type="primary" :loading="planRef?.saving" @click="planRef?.save()">保存付款计划</el-button></template></el-dialog></template>
